 "research_concepts": [
  "concept"
 ],
 "methodological_questions": [
  "question"
 ],
 "historical_evidence": [
  {
   "id": "identifier of a record returned by a tool",
   "status_as_recorded": "outcome status exactly as stated in the record (supported | rejected | inconclusive | untestable | artifact | not a hypothesis test | no result recorded)",
   "finding": "what the record states, in its own terms"
  }
 ],
 "failed_approaches": [
  {
   "id": "identifier of a returned record",
   "what_failed": "approach",
   "why": "failure mechanism or limitation as recorded"
  }
 ],
 "evidence_establishes": [
  "what the retrieved evidence establishes for this question"
 ],
 "evidence_does_not_establish": [
  "what it leaves open or cannot show"
 ],
 "own_inferences": [
  "your inference, not stated in any record"
 ],
 "uncertainties": [
  "uncertainty or missing information"
 ],
 "historical_effect": {
  "changed_decision": "yes | no | no_historical_evidence",
  "explanation": "whether and how the historical evidence changed the decision"
 },
 "testability": {
  "p_testable": "number in [0,1]: probability the question can be answered with the stated data at useful power",
  "blocking_constraints": [
   {
    "code": "one of RISK_CODES",
    "text": "string"
   }
  ]
 },
 "prior_work": {
  "already_answered": "yes | partly | no | unknown",
  "cited": [
   "identifiers of prior work relied on"
  ],
  "summary": "string"
 },
 "risks": [
  {
   "code": "one of RISK_CODES",
   "text": "string"
  }
 ],
 "predicted_outcome": {
  "supported": "probability",
  "rejected": "probability",
  "untestable": "probability",
  "artifact": "probability",
  "uncertain": "probability"
 },
 "decision": "proceed | proceed_with_changes | do_not_proceed",
 "design": {
  "estimand": "string",
  "unit": "string",
  "sample": "string",
  "power": "string",
  "controls": "string",
  "falsification": "string",
  "multiplicity": "string",
  "decision_rule": "string",
  "data_version": "string"
 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).

{"action": "final", "output": {
  "research_concepts": [
    "teammate DRIVE",
    "pick and roll (PNR)",
    "points per possession (PPP)",
    "play sequence (X -> Y within same possession)",
    "preceding actions",
    "sequential premium"
  ],
  "methodological_questions": [
    "How to define temporal precedence within a possession?",
    "What confounding factors affect PNR efficiency?",
    "Is there sufficient sample size of sequences with teammate DRIVE then PNR?",
    "How to isolate the effect of a preceding DRIVE from game context and defensive adjustments?",
    "Are play-type labels reliable for identifying drives and PNRs?",
    "Does labeling bias (foul leakage, context-dependent tagging) inflate or deflate sequential premiums?"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-APPA-058",
      "status_as_recorded": "rejected",
      "finding": "Only 2/30 stars had a stable same top suppressor across seasons. Negative teammate pair: Giannis->Lillard DRIVE->PNR -0.263 (n=31)."
    },
    {
      "id": "FAM:SF40",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Top teammate sequences: J. Brown->J. Tatum DRIVE->PNR +0.326 (n=43, later flagged as placebo artifact). D. Bane DRIVE->PNR -0.324 (n=70). Many cells DIRECTIONAL with n<50."
    },
    {
      "id": "FAM:SF-APPS-012",
      "status_as_recorded": "not a hypothesis test",
      "finding": "PNR share jumps +12.1pp playoffs vs RS possibly due to tagging differences; DRIVE allowed PPP drops -0.268."
    },
    {
      "id": "FAM:SF-APPM-058",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Shot-level PNR share ranges 7.6–13.8% across teams; used for calibration of possession-level PNR labels."
    },
    {
      "id": "FAM:SF-CHT-025",
      "status_as_recorded": "artifact",
      "finding": "Only 0.7% of possessions map to a play type via initiation_type. DRIVE PPP understated by 12pp due to foul leakage; OTHER PPP inflated by 36% foul endings."
    },
    {
      "id": "FAM:SF-APPM-033",
      "status_as_recorded": "inconclusive",
      "finding": "Brown->Tatum DRIVE->PNR +0.326 later removed: 'doesn't hold up'. Sequence premiums abandoned for unknown reasons."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPA-058",
      "what_failed": "Attempt to find stable teammate sequential suppressors (e.g., negative premiums) across seasons",
      "why": "Only 7% of stars had a stable top suppressor; small sample per cell (min n=20)."
    },
    {
      "id": "FAM:SF40",
      "what_failed": "Descriptive listing of teammate DRIVE->PNR premiums without multiplicity control",
      "why": "Most cells directional with n<50; later shown a positive DRIVE->PNR premium was a placebo artifact."
    },
    {
      "id": "FAM:SF-CHT-025",
      "what_failed": "Assuming play-type PPP differences reflect true efficiency",
      "why": "Labeling artifacts: DRIVE PPP understated due to foul leakage; only 0.7% mapping via initiation_type."
    },
    {
      "id": "FAM:SF-APPM-033",
      "what_failed": "Sequential conditioning premium analysis including DRIVE->PNR",
      "why": "Results abandoned; a specific positive DRIVE->PNR pair did not hold up (placebo artifact)."
    }
  ],
  "evidence_establishes": [
    "Teammate DRIVE->PNR sequence premiums have been observed but with mixed signs (both positive and negative), small sample sizes (n=30–70), and at least one previously reported positive premium (Brown->Tatum) was later identified as a placebo artifact.",
    "Play-type labeling for DRIVE suffers from systematic foul leakage that depresses DRIVE PPP by approximately 12 percentage points.",
    "PNR possession labels may shift across contexts (e.g., regular season vs playoffs) due to tagging inconsistencies.",
    "The initiation_type mapping captures only 0.7% of possessions, indicating substantial labeling uncertainty."
  ],
  "evidence_does_not_establish": [
    "Whether any true causal or robust sequential premium exists for a teammate DRIVE preceding a PNR.",
    "Whether positive DRIVE->PNR premiums generalize beyond a few specific player pairs or survive correction for labeling artifacts and multiple testing.",
    "Whether the labeled sequence 'DRIVE then PNR' corresponds to a clean, distinct tactical phenomenon or is contaminated by foul-drawing drives, defensive switches, or ambiguous possession tagging."
  ],
  "own_inferences": [
    "The combination of small cell sizes, labeling artifacts, and the documented placebo effect makes it very unlikely that a test of 'Any teammate DRIVE preceding a PNR raises PNR PPP' can attain useful statistical power with the current data.",
    "Foul leakage on DRIVE labels could systematically bias the PPP of drives downward, which would inflate any apparent sequential premium if the subsequent PNR is not similarly affected.",
    "Defensive adjustments after a drive (e.g., help rotations, switching) could confound the PNR efficiency in ways that are difficult to control for without granular tracking data."
  ],
  "uncertainties": [
    "Whether the calibrated PBPProxyPNR labels (referenced in FAM:SF-APPM-058) would improve labeling reliability enough to rescue the analysis.",
    "The exact criteria used to link a DRIVE and a subsequent PNR to the same possession and same teammate, and how robust those links are to clock and substitution mismatches.",
    "Whether sufficient sample size exists when restricting to specific teammate pairs and game contexts to yield a precise estimate."
  ],
