        "code": "PLACEBO_DEPENDENCE",
        "text": "A previously reported positive teammate DRIVE->PNR premium (Brown->Tatum) was later flagged as a placebo artifact. This raises the prior probability that any observed effect is spurious."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "Testing 'any teammate DRIVE' implicitly involves many player-pair combinations. Unless a global aggregated test with appropriate shrinkage is prespecified, the probability of false positives is high."
      }
    ]
  },
  "prior_work": {
    "already_answered": "partly",
    "cited": [
      "FAM:SF40",
      "FAM:SF-APPM-033",
      "FAM:SF-CHT-025"
    ],
    "summary": "Earlier work explored teammate sequential premiums including DRIVE->PNR and found mixed signs, small samples, and at least one artifact. The question has not been definitively answered because reported positive premiums were later discredited, and no study has tested the global hypothesis 'any teammate DRIVE raises PNR PPP' with corrected labels and rigorous controls."
  },
  "risks": [
    {
      "code": "LABEL_ERROR",
      "text": "Systematic understatement of DRIVE PPP due to foul leakage; ambiguous possession tagging; 0.7% mapping rate may exclude most real sequences."
    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Pooled across all teammate pairs, the number of DRIVE->PNR sequences within the same possession may still be insufficient to detect a plausible effect size (e.g., +0.03 PPP) with power >0.8 given high possession-level variance."
    },
    {
      "code": "PLACEBO_DEPENDENCE",
      "text": "Historical record shows at least one apparent positive DRIVE->PNR premium was a placebo artifact; the present test would need to rule out a similar artifact."
    },
    {
      "code": "CONFOUNDING",
      "text": "Defensive strategy (e.g., switching, help rotations) after a drive may affect the subsequent PNR, creating a spurious association if not controlled."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "If the test is conducted pair-by-pair, the large number of teammate combinations inflates Type I error; if aggregated, the question 'any teammate' may be too vague and mask genuine heterogeneity."
    },
    {
      "code": "DRIFT_NONSTATIONARITY",
      "text": "Labeling distributions and team play-style change across seasons and between regular season and playoffs, potentially invalidating pooled estimates."
    }
  ],
  "predicted_outcome": {
    "supported": 0.1,
    "rejected": 0.25,
    "untestable": 0.35,
    "artifact": 0.2,
    "uncertain": 0.1
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "The difference in PNR points per possession when the PNR is immediately preceded by a teammate DRIVE (within the same offensive possession) versus when it is not, controlling for game score, period, defensive team, and possession start state.",
    "unit": "A PNR possession as recorded in the play-type possession graph, with the sequence DRIVE (by a different player on the same team) -> PNR within the same 24-second clock event.",
    "sample": "NBA 2022-23, 2023-24, 2024-25, and 2025-26 regular seasons (playoffs omitted due to documented PNR share drift). Only possessions where both the DRIVE and the subsequent PNR are labeled with high confidence (e.g., using a calibrated PBP proxy that corrects for foul leakage and mapping gaps).",
    "power": "For a minimum detectable effect of +0.03 PPP (roughly 0.1 standard deviations of possession-level PPP), with alpha=0.01 and power=0.9, approximately 5,000-7,000 DRIVE->PNR sequences would be needed. Historical evidence suggests only a few hundred exist even across all teams, so the test is underpowered.",
    "controls": "Fixed effects for offensive team, defensive team, period, score differential (binned), and possession start state (after made basket, defensive rebound, sideline out-of-bounds, etc.).",
    "falsification": "Test whether a subsequent PNR that is NOT preceded by a teammate DRIVE but is preceded by an equivalent 'non-action' (e.g., a dribble reset or an off-ball cut) yields a similar premium. Also test for placebo sequences where the DRIVE occurs after the PNR or in an unrelated possession.",
    "multiplicity": "Pre-register a single global hypothesis: the weighted average of the conditional DRIVE->PNR premium across all teammate pairs (with shrinkage via hierarchical Bayesian model) is positive. No per-pair tests unless the global test is significant and then with FDR control.",
    "decision_rule": "Reject the null if the Bayesian posterior probability that the global premium > 0 exceeds 0.95, using a weakly informative prior centered at zero. Additionally, require that the effect withstands a leave-one-season-out cross-validation and is not driven by a single player pair.",
    "data_version": "Play-type possession records from the graph database as of 2026-06-14, augmented with the foul-leakage-corrected PBP proxy labels developed in SF-APPM-058 and SF-CHT-025 follow-up. Minimum 10 possessions per pair to be included in aggregation."
  }
}}

